-- ─────────────────────────────────────────────────────────────────────────
-- Bootstrap step 2 of 2 — derive the real baseline from the Prisma schema.
--
-- Step 1 (001_from_prisma.sql) is the schema exactly as Prisma emitted it:
-- ISO-8601 timestamps stored as `text`, and money split between integer cents
-- (store) and `double precision` USD (bookings, appointments).
--
-- This script fixes both, in place, on a seeded database. `petapp.sql` — the
-- master everything else is created from — is then generated by pg_dump FROM
-- the converted database, so the master and the data can never disagree.
--
-- This runs ONCE, during bootstrap. It is not a `changes/` migration; by the
-- time anything is deployed, `petapp.sql` already contains its effects.
-- ─────────────────────────────────────────────────────────────────────────

BEGIN;

-- ── 1. Script journal ────────────────────────────────────────────────────
-- Every future db/changes/NNN_*.sql records itself here, so any server can be
-- asked what it holds: SELECT * FROM schema_version ORDER BY applied_at;

CREATE TABLE IF NOT EXISTS schema_version (
  script     text PRIMARY KEY,
  applied_at timestamptz NOT NULL DEFAULT now()
);

-- ── 2. Money → integer cents ─────────────────────────────────────────────
-- The store was already integer cents; bookings and vet appointments were
-- `double precision` USD. Floats drift under arithmetic and an amount charged
-- to somebody must not. Unifying now is what makes payouts possible later —
-- ROADMAP.md flags the split as the thing that will hurt.
--
-- The API still emits USD at the DTO boundary (cents / 100m), so the contract
-- in types/index.ts is unchanged.

ALTER TABLE "pricing_entries"  ADD COLUMN "rateCents"       integer;
ALTER TABLE "bookings"         ADD COLUMN "priceTotalCents" integer;
ALTER TABLE "vet_profiles"     ADD COLUMN "consultFeeCents" integer;
ALTER TABLE "vet_appointments" ADD COLUMN "baseFeeCents"    integer;
ALTER TABLE "vet_appointments" ADD COLUMN "feeCents"        integer;

UPDATE "pricing_entries"  SET "rateCents"       = round("rate"        * 100)::int;
UPDATE "bookings"         SET "priceTotalCents" = round("priceTotal"  * 100)::int;
UPDATE "vet_profiles"     SET "consultFeeCents" = round("consultFee"  * 100)::int;
UPDATE "vet_appointments" SET "baseFeeCents"    = round("baseFee"     * 100)::int,
                              "feeCents"        = round("fee"         * 100)::int;

ALTER TABLE "pricing_entries"  ALTER COLUMN "rateCents"       SET NOT NULL;
ALTER TABLE "bookings"         ALTER COLUMN "priceTotalCents" SET NOT NULL;
ALTER TABLE "vet_profiles"     ALTER COLUMN "consultFeeCents" SET NOT NULL;
ALTER TABLE "vet_appointments" ALTER COLUMN "baseFeeCents"    SET NOT NULL;
ALTER TABLE "vet_appointments" ALTER COLUMN "feeCents"        SET NOT NULL;
ALTER TABLE "vet_appointments" ALTER COLUMN "baseFeeCents"    SET DEFAULT 0;

ALTER TABLE "pricing_entries"  DROP COLUMN "rate";
ALTER TABLE "bookings"         DROP COLUMN "priceTotal";
ALTER TABLE "vet_profiles"     DROP COLUMN "consultFee";
ALTER TABLE "vet_appointments" DROP COLUMN "baseFee";
ALTER TABLE "vet_appointments" DROP COLUMN "fee";

-- ── 3. Columns that need clearing before the type change ─────────────────
-- `lastEventAt` is `text NOT NULL DEFAULT ''` — "we have never heard from the
-- provider" encoded as an empty string. NULL is the honest representation and
-- the only one a timestamptz column can hold, so the constraint goes.

ALTER TABLE "payments"      ALTER COLUMN "lastEventAt" DROP DEFAULT,
                            ALTER COLUMN "lastEventAt" DROP NOT NULL;
ALTER TABLE "subscriptions" ALTER COLUMN "lastEventAt" DROP DEFAULT,
                            ALTER COLUMN "lastEventAt" DROP NOT NULL;

-- A valid timestamp, but the default is a text literal and cannot survive the
-- cast. Dropped here, restored as a timestamptz in step 6.
ALTER TABLE "pets" ALTER COLUMN "ownedSince" DROP DEFAULT;

-- ── 4. Calendar dates → `date` ───────────────────────────────────────────
-- These three are days, not instants. Storing them as timestamptz would invent
-- a time and a timezone, which is exactly how availability picks up
-- off-by-one-day bugs.

ALTER TABLE "pets"                  ALTER COLUMN "dob"  TYPE date USING "dob"::date;
ALTER TABLE "availability_days"     ALTER COLUMN "date" TYPE date USING "date"::date;
ALTER TABLE "vet_availability_days" ALTER COLUMN "date" TYPE date USING "date"::date;

-- ── 5. Everything else → `timestamptz` ───────────────────────────────────
-- 59 columns across 25 tables. Done in a loop rather than by hand: the
-- transformation is identical for every one, and 59 hand-written ALTERs is 59
-- chances to mistype a column name.
--
-- NULLIF(col,'') covers the emptied columns from step 3.

DO $$
DECLARE r record;
BEGIN
  FOR r IN
    SELECT table_name AS t, column_name AS c
    FROM information_schema.columns
    WHERE table_schema = 'public'
      AND data_type = 'text'
      AND ( column_name ~* '(At|Since|expires|Start|End)$'
         OR column_name ~* 'DateTime$' )
    ORDER BY table_name, column_name
  LOOP
    EXECUTE format(
      'ALTER TABLE %I ALTER COLUMN %I TYPE timestamptz USING NULLIF(%I, %L)::timestamptz',
      r.t, r.c, r.c, ''
    );
    RAISE NOTICE 'timestamptz: %.%', r.t, r.c;
  END LOOP;
END $$;

-- ── 6. Restore the default that step 3 dropped ───────────────────────────
-- Epoch, meaning "we have no record of when this animal was acquired". Read by
-- the access predicates: an engagement created before this instant grants no
-- record access. See lib/server/access.ts.

ALTER TABLE "pets"
  ALTER COLUMN "ownedSince" SET DEFAULT '1970-01-01T00:00:00Z'::timestamptz;

-- ── 7. Record it ─────────────────────────────────────────────────────────

INSERT INTO schema_version (script) VALUES
  ('001_from_prisma'),
  ('002_cents_and_timestamps')
ON CONFLICT (script) DO NOTHING;

COMMIT;
